import requests
import json

class SnowflakeMCPClient:
    def __init__(self, endpoint_url, oauth_token):
        self.endpoint_url = endpoint_url
        self.headers = {
            'Authorization': f'Bearer {oauth_token}',
            'Content-Type': 'application/json'
        }

    def initialize(self):
        payload = {
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'initialize',
            'params': {}
        }
        return requests.post(self.endpoint_url, json=payload, headers=self.headers).json()

    def list_tools(self):
        payload = {
            'jsonrpc': '2.0',
            'id': 2,
            'method': 'tools/list',
            'params': {}
        }
        return requests.post(self.endpoint_url, json=payload, headers=self.headers).json()

    def call_tool(self, tool_name, arguments):
        payload = {
            'jsonrpc': '2.0',
            'id': 3,
            'method': 'tools/call',
            'params': {
                'name': tool_name,
                'arguments': arguments
            }
        }
        return requests.post(self.endpoint_url, json=payload, headers=self.headers).json()

# Usage
client = SnowflakeMCPClient(
    endpoint_url='https://myaccount.snowflakecomputing.com/api/v2/databases/GHOST_DETECTION/schemas/APP/mcp-servers/GHOST_DETECTION_MCP_SERVER',
    oauth_token='<your_oauth_token>'
)

# Initialize
result = client.initialize()
print(result)

# List tools
tools = client.list_tools()
print(tools)

# Search for ghosts
result = client.call_tool('ghost-search', {'query': 'shadow entity', 'limit': 5})
print(result)
